import {APP_VERSION,SCENARIOS,DIFFICULTIES,ROLE_LIBRARY,CATEGORY_LABELS,GENRE_LABELS,TOPIC_LABELS} from './data.js';
import {storage,subscribe,migrateStorage} from './storage.js';
import {createSession,createImportedSession,getSession,saveSession,allSessions,findTeamByCode,renameTeam,deleteSession,duplicateSession,addMember,removeMember,moveMember,setRole} from './session.js';
import {initialProgress,loadProgress,saveProgress,activeSteps,submitAnswer,useHint,finish,derivedWorldCode,validateWorldCode,currentWorldIndex,ensureStepClock,solutionAvailable,solutionWait} from './engine.js';
import {esc,fmt,toast,metric} from './ui.js';
import {initAccessibility,announce} from './accessibility.js';
import {hostPinExists,hostUnlocked,setHostPin,verifyHostPin,lockHost} from './host-auth.js';
import {makeTeamLink,parseTeamPayload} from './share.js';

migrateStorage(5);
const app=document.getElementById('app');
let state={scenario:null,session:null,team:null,progress:null,hint:null,feedback:null,recap:null,filters:{q:'',category:'all',genre:'all',audience:'all',format:'all'},selectedDifficulty:'aventure',terminalTeamId:null};
let ticker=null;
const byId=id=>SCENARIOS.find(s=>s.id===id);
const genreLabel=s=>GENRE_LABELS[s.genre]||s.genre||'Jeu immersif';
function hexToRgb(h){h=h.replace('#','');return [parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)].join(',')}
function theme(s){if(!s)return'';return `style="--accent:${s.accent};--accent-rgb:${hexToRgb(s.accent)}" data-genre="${esc(s.genre||'')}"`}
function topbar({player=false,extra=''}={}){return `<header class="topbar"><div class="topbar-inner"><button class="brand btn ghost" data-nav="home" aria-label="Accueil FAFA QUEST"><span class="brand-mark">FQ</span><span>FAFA QUEST<small>FAFATRAINING • ESCAPE • IMMERSION</small></span></button><div class="nav-actions">${player?'<button class="btn ghost" data-nav="home">Quitter</button>':`<button class="btn ghost optional" data-nav="library">Bibliothèque</button><button class="btn ghost optional" data-nav="ado">Questions d’ados</button><button class="btn secondary" data-nav="host">Animateur</button>`}${extra}</div></div></header>`}
function shell(content,s=null,opts={}){return `${topbar(opts)}<main class="shell ${s?'immersive-shell':''}" ${theme(s)}>${content}</main><footer class="footer">FAFA QUEST v${APP_VERSION} • FAFATRAINING • Téléphone • tablette • ordinateur • TV</footer>`}
function bindNav(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav))}
function go(h){location.hash='#'+h}
function registerSW(){if(!('serviceWorker'in navigator))return;navigator.serviceWorker.register('./sw.js').then(reg=>{reg.addEventListener('updatefound',()=>{const nw=reg.installing;nw?.addEventListener('statechange',()=>{if(nw.state==='installed'&&navigator.serviceWorker.controller)showUpdateBanner(reg)})})}).catch(()=>{})}
function showUpdateBanner(reg){if(document.getElementById('update-banner'))return;document.body.insertAdjacentHTML('beforeend',`<div class="update-banner" id="update-banner"><strong>Nouvelle version disponible</strong><button class="btn primary small" id="update-now">Mettre à jour</button><button class="btn ghost small" id="update-later">Plus tard</button></div>`);document.getElementById('update-now').onclick=()=>{reg.waiting?.postMessage({type:'SKIP_WAITING'});location.reload()};document.getElementById('update-later').onclick=()=>document.getElementById('update-banner').remove()}
function sound(ok=true){try{const C=window.AudioContext||window.webkitAudioContext,c=new C(),o=c.createOscillator(),g=c.createGain();o.frequency.value=ok?660:180;g.gain.value=.035;o.connect(g);g.connect(c.destination);o.start();setTimeout(()=>{o.stop();c.close()},ok?120:180)}catch{}}
function challengeDots(n=2){return `<span class="challenge" aria-label="Intensité ${n} sur 4">${'●'.repeat(n)}${'○'.repeat(4-n)}</span>`}
function ageMatch(s,v){if(v==='all')return true;return (s.audience||[]).includes(v)}
function sessionRemaining(s){if(!s.startedAt)return s.durationMin*60000;const ref=s.pausedAt||Date.now();const spent=ref-s.startedAt-(s.pausedTotalMs||0);return Math.max(0,s.durationMin*60000-spent)}
function playerElapsed(p,s){if(!p?.startedAt)return 0;const end=p.finishedAt||Date.now();let paused=s?.pausedTotalMs||0;if(s?.pausedAt&&!p.finishedAt)paused+=Math.max(0,Date.now()-s.pausedAt);return Math.max(0,end-p.startedAt-paused)}
function timerClass(ms){return ms<=60000?'critical':ms<=300000?'danger':ms<=600000?'warn':''}
function isStrictTimeUp(s){return s?.timerMode==='strict'&&s.startedAt&&sessionRemaining(s)<=0}

function home(){
  const adoCount=SCENARIOS.filter(s=>s.genre==='questions_ados').length;
  app.innerHTML=shell(`<section class="hero"><div><div class="eyebrow">ESCAPE • GRAND JEU • ENQUÊTE • QUESTIONS D’ADOS</div><h1>FAFA <span>QUEST</span></h1><p>Une plateforme de jeux immersifs pour jouer vraiment : salles, fouille, codes, objets, réflexion, coopération, chronomètre et scénarios à impact. L’écran guide l’aventure sans remplacer les joueurs.</p><div class="actions"><button class="btn primary" data-nav="library">Explorer les jeux</button><button class="btn secondary" data-nav="recommend">Quel jeu choisir ?</button><button class="btn ghost" data-nav="ado">Questions d’ados (${adoCount})</button></div><div class="scenario-meta" style="margin-top:18px"><span class="tag">${SCENARIOS.length} jeux</span><span class="tag">4 niveaux</span><span class="tag">Écran central / TV</span><span class="tag">Hors connexion</span></div></div><div class="hero-art"><div class="quest-symbol">⌁</div><div class="hero-orbit orbit-a"></div><div class="hero-orbit orbit-b"></div></div></section><section class="grid cols-3"><article class="card"><div class="eyebrow">JOUER</div><h2>Immersion d’abord</h2><p class="muted">Chaque jeu possède un univers, une progression et des mécaniques propres : pas une succession de QCM identiques.</p></article><article class="card"><div class="eyebrow">COOPÉRER</div><h2>Tout le monde participe</h2><p class="muted">Rôles, informations distribuées, rotation des salles et variantes d’équipe évitent qu’une seule personne monopolise le jeu.</p></article><article class="card"><div class="eyebrow">ANIMER</div><h2>Un vrai outil pro</h2><p class="muted">Tableau animateur, écran public séparé, chronomètre, kits imprimables, équipes et mode test.</p></article></section>`);bindNav()
}
function scenarioCard(s){return `<article class="card scenario-card" style="--scenario-accent:${s.accent}"><div class="scenario-cover genre-${esc(s.genre)}"><div class="scenario-icon">${esc(s.icon)}</div><div class="cover-genre">${esc(genreLabel(s))}</div></div><div class="eyebrow">${esc(CATEGORY_LABELS[s.category]||s.category)}</div><h2>${esc(s.title)}</h2><p class="muted">${esc(s.subtitle)}</p><div class="scenario-meta"><span class="tag">${esc(s.age)}</span><span class="tag">${s.durationMin} min</span><span class="tag">${esc(s.players)}</span><span class="tag">${challengeDots(s.challenge||2)}</span>${s.formats.includes('central')?'<span class="tag">TV / salles</span>':''}${s.formats.includes('hybride')?'<span class="tag">Papier + objets</span>':''}${s.formats.includes('numerique')?'<span class="tag">100 % numérique</span>':''}</div><p>${esc(s.description)}</p><div class="actions"><button class="btn primary" data-detail="${s.id}">Voir le jeu</button><button class="btn ghost" data-start="${s.id}">Créer une partie</button></div></article>`}
function library(){
  let items=SCENARIOS.filter(s=>{const f=state.filters,q=f.q.toLowerCase();const blob=(s.title+' '+s.subtitle+' '+s.description+' '+(s.mechanics||[]).join(' ')+' '+genreLabel(s)).toLowerCase();return (!q||blob.includes(q))&&(f.category==='all'||s.category===f.category)&&(f.genre==='all'||s.genre===f.genre)&&ageMatch(s,f.audience)&&(f.format==='all'||s.formats.includes(f.format))});
  const genreOptions=Object.entries(GENRE_LABELS).map(([id,l])=>`<option value="${id}">${esc(l)}</option>`).join('');
  app.innerHTML=shell(`<div class="section-title"><div><div class="eyebrow">BIBLIOTHÈQUE</div><h1>Choisis un type de jeu, un public et une ambiance.</h1></div><span class="tag">${items.length}/${SCENARIOS.length}</span></div><div class="filterbar filterbar-5"><div class="field"><label>Rechercher</label><input id="f-q" value="${esc(state.filters.q)}" placeholder="cyber, enquête, harcèlement, maths…"></div><div class="field"><label>Famille de jeux</label><select id="f-cat"><option value="all">Toutes</option><option value="fun">Escape & aventures</option><option value="education">Défis & connaissances</option><option value="impact">Questions d’ados & société</option></select></div><div class="field"><label>Genre</label><select id="f-genre"><option value="all">Tous les genres</option>${genreOptions}</select></div><div class="field"><label>Public</label><select id="f-aud"><option value="all">Tous</option><option value="enfant">Enfant</option><option value="ado">Ado</option><option value="adulte">Adulte</option><option value="famille">Famille</option></select></div><div class="field"><label>Format</label><select id="f-format"><option value="all">Tous</option><option value="central">TV / salles</option><option value="hybride">Hybride physique</option><option value="numerique">Numérique</option><option value="equipe">Équipe</option></select></div></div>${Object.keys(GENRE_LABELS).map(g=>{const group=items.filter(x=>x.genre===g);return group.length?`<section><div class="section-title"><div><div class="eyebrow">${esc(GENRE_LABELS[g])}</div><h2>${g==='questions_ados'?'Des sujets réels traités comme des jeux':'Des mécaniques adaptées à cet univers'}</h2></div><span class="tag">${group.length}</span></div><div class="grid cols-3">${group.map(scenarioCard).join('')}</div></section>`:''}).join('')}`);
  bindNav();const map={cat:'category',genre:'genre',aud:'audience',format:'format'};Object.entries(map).forEach(([k,p])=>{const el=document.getElementById('f-'+k);el.value=state.filters[p];el.onchange=()=>{state.filters[p]=el.value;library()}});let t;document.getElementById('f-q').oninput=e=>{clearTimeout(t);state.filters.q=e.target.value;t=setTimeout(library,180)};document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>sessionBuilder(b.dataset.start))
}
function adoWorld(){const games=SCENARIOS.filter(s=>s.genre==='questions_ados');const groups=Object.entries(TOPIC_LABELS).map(([id,label])=>({id,label,games:games.filter(s=>s.topic===id)})).filter(g=>g.games.length);app.innerHTML=shell(`<section class="ado-hero"><div class="eyebrow">MONDE QUESTIONS D’ADOS</div><h1>Des sujets réels. Des mécaniques différentes.</h1><p>Harcèlement, violence, image, réseaux, IA, pression du groupe, limites, prévention… Chaque thème possède son propre gameplay : faux téléphone, dossier, chronologie, enquête, fichiers, décisions ou coopération. Aucun scénario ne demande aux jeunes de raconter leur vie personnelle.</p><div class="scenario-meta"><span class="tag">${games.length} jeux</span><span class="tag">11–17 ans</span><span class="tag">Débrief animateur</span><span class="tag">Situations fictives</span></div></section>${groups.map(g=>`<section><div class="section-title"><div><div class="eyebrow">${esc(g.label)}</div><h2>${g.games.length} jeu${g.games.length>1?'x':''}</h2></div></div><div class="grid cols-3">${g.games.map(scenarioCard).join('')}</div></section>`).join('')}<section class="card safety-card"><h2>Principe pédagogique</h2><p>On joue d’abord, on débriefe ensuite. Les contenus sont fictifs, mixtes, sans collecte de confidences personnelles. Quand un repère de prévention est donné, sa source est affichée dans la fiche du jeu.</p></section>`);bindNav();document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>sessionBuilder(b.dataset.start))}
function recommend(){app.innerHTML=shell(`<div class="section-title"><div><div class="eyebrow">SÉLECTEUR</div><h1>Quel jeu choisir ?</h1></div></div><section class="card"><div class="form-grid"><div class="field"><label>Public</label><select id="r-aud"><option value="enfant">Enfant / famille</option><option value="ado" selected>Ado 11–17 ans</option><option value="adulte">Adulte</option><option value="famille">Famille mixte</option></select></div><div class="field"><label>Temps disponible</label><select id="r-time"><option value="45">45 min ou moins</option><option value="60" selected>Environ 1 h</option><option value="90">Jusqu’à 1 h 30</option></select></div><div class="field"><label>Installation</label><select id="r-format"><option value="equipe">Simple / téléphone par équipe</option><option value="hybride">Avec objets et cachettes</option><option value="central">Plusieurs salles + TV</option></select></div><div class="field"><label>Envie</label><select id="r-genre"><option value="all">Surprends-moi</option>${Object.entries(GENRE_LABELS).map(([id,l])=>`<option value="${id}">${esc(l)}</option>`).join('')}</select></div></div><button class="btn primary" id="r-go" style="margin-top:16px">Proposer 3 jeux</button></section><div id="r-results"></div>`);bindNav();document.getElementById('r-go').onclick=()=>{const aud=document.getElementById('r-aud').value,time=+document.getElementById('r-time').value,format=document.getElementById('r-format').value,genre=document.getElementById('r-genre').value;let arr=SCENARIOS.map(s=>({s,score:(ageMatch(s,aud)?5:0)+(s.durationMin<=time?3:0)+(s.formats.includes(format)?4:0)+(genre==='all'||s.genre===genre?3:0)})).sort((a,b)=>b.score-a.score).slice(0,3).map(x=>x.s);document.getElementById('r-results').innerHTML=`<div class="section-title"><h2>Mes 3 propositions</h2></div><div class="grid cols-3">${arr.map(scenarioCard).join('')}</div>`;document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>sessionBuilder(b.dataset.start))}}
function detail(id){const s=byId(id);if(!s)return;app.innerHTML=shell(`<section class="card scenario-card detail-hero" style="--scenario-accent:${s.accent}"><div class="scenario-cover detail-cover genre-${esc(s.genre)}"><div class="scenario-icon">${esc(s.icon)}</div><div class="cover-genre">${esc(genreLabel(s))}</div></div><div class="eyebrow">${esc(CATEGORY_LABELS[s.category]||'Jeu')}</div><h1>${esc(s.title)}</h1><p class="muted detail-subtitle">${esc(s.subtitle)}</p><div class="metric-row">${metric('Âge',s.age)}${metric('Durée',s.durationMin+' min')}${metric('Équipe',s.players)}${metric('Intensité',(s.challenge||2)+'/4')}</div>${s.topic?`<div class="topic-banner">${esc(TOPIC_LABELS[s.topic]||s.topic)}</div>`:''}<p class="detail-copy">${esc(s.description)}</p><div class="actions"><button class="btn primary" id="detail-start">Créer une partie</button><button class="btn secondary" id="detail-test">Mode test</button><button class="btn ghost" id="detail-lib">Retour</button></div></section><div class="grid cols-2" style="margin-top:16px"><section class="card"><h2>Mécaniques</h2><ul class="mechanic-list">${s.mechanics.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="card"><h2>Formats</h2><p>${s.formats.includes('central')?'<strong>TV / salles :</strong> rotation possible, terminal central et codes distincts par équipe.<br><br>':''}<strong>Équipe :</strong> ${s.formats.includes('numerique')?'guidage téléphone/tablette. ':'application en support du jeu. '}${s.formats.includes('hybride')?'Objets, cachettes ou manipulations possibles.':''}</p></section><section class="card"><h2>Matériel</h2><ul>${(s.materials||['Aucun matériel spécifique']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="card"><h2>Préparation</h2><ol class="setup-list">${(s.setup||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>${s.cast?`<section class="card"><h2>Personnages fictifs</h2><div class="role-grid">${s.cast.map(c=>`<div class="role-card"><strong>${esc(c.name)}</strong><div class="muted">${esc(c.role)}</div></div>`).join('')}</div></section>`:''}${s.playStyles?`<section class="card"><h2>Deux façons de jouer</h2>${s.playStyles.digital?`<p><strong>Numérique :</strong> ${esc(s.playStyles.digital)}</p>`:''}${s.playStyles.hybrid?`<p><strong>Hybride :</strong> ${esc(s.playStyles.hybrid)}</p>`:''}</section>`:''}${s.sourceOrigins?`<section class="card source-origin"><h2>Conception / adaptation</h2><ul>${s.sourceOrigins.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`:''}${s.sources?`<section class="card"><h2>Repères documentaires</h2><ul>${s.sources.map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.label)}</a></li>`).join('')}</ul></section>`:''}</div>${s.debrief?`<section class="debrief"><h2>Débrief animateur</h2><ul>${s.debrief.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`:''}`,s);bindNav();document.getElementById('detail-start').onclick=()=>sessionBuilder(id);document.getElementById('detail-test').onclick=()=>go('test/'+id);document.getElementById('detail-lib').onclick=()=>go('library')}

async function hostGate(){if(hostUnlocked())return go(sessionStorage.getItem('fafaquest-host-next')||'host');const exists=hostPinExists();app.innerHTML=shell(`<section class="card auth-card"><div class="eyebrow">MODE ANIMATEUR PROTÉGÉ</div><h1>${exists?'Entrer le code animateur':'Créer le code animateur'}</h1><p class="muted">Protection locale contre les accès accidentels des joueurs. Ce code reste sur cet appareil.</p><div class="field"><label>Code 4 à 8 chiffres</label><input id="host-pin" type="password" inputmode="numeric" maxlength="8" autocomplete="off"></div><button class="btn primary block" id="host-pin-go" style="margin-top:14px">${exists?'Déverrouiller':'Créer et déverrouiller'}</button></section>`);bindNav();document.getElementById('host-pin-go').onclick=async()=>{const pin=document.getElementById('host-pin').value;try{const ok=exists?await verifyHostPin(pin):await setHostPin(pin);if(ok){const next=sessionStorage.getItem('fafaquest-host-next')||'host';sessionStorage.removeItem('fafaquest-host-next');go(next)}else toast('Code animateur incorrect.','error')}catch(e){toast(e.message,'error')}}}
function sessionBuilder(preselected){if(!hostUnlocked()){sessionStorage.setItem('fafaquest-host-next','build/'+(preselected||''));return go('host-gate')}const sid=preselected||SCENARIOS[0].id,s=byId(sid);state.selectedDifficulty=s.recommendedDifficulty||'aventure';app.innerHTML=shell(`<div class="section-title"><div><div class="eyebrow">ANIMATEUR</div><h1>Créer une partie</h1></div></div><section class="card"><div class="form-grid"><div class="field"><label>Jeu</label><select id="b-scenario">${SCENARIOS.map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select></div><div class="field"><label>Format</label><select id="b-mode"><option value="central" ${s.formats.includes('central')?'selected':''}>TV / écran central + salles</option><option value="team_device" ${!s.formats.includes('central')?'selected':''}>1 appareil par équipe</option><option value="solo">Un seul appareil / famille</option></select></div><div class="field"><label>Nombre d’équipes</label><input id="b-teams" type="number" min="1" max="12" value="3"></div><div class="field"><label>Durée de base</label><input id="b-duration" type="number" min="10" max="180" value="${s.durationMin}"></div><div class="field"><label>Chronomètre</label><select id="b-timer"><option value="host">Animateur décide à 00:00</option><option value="strict">Fin stricte à 00:00</option><option value="loisir">Indicatif seulement</option></select></div><div class="field"><label>Rotation des salles</label><select id="b-rotation"><option value="yes">Oui — départs répartis</option><option value="no">Non — tout le monde commence au monde 1</option></select></div></div><h3>Niveau</h3><div class="difficulty-grid">${DIFFICULTIES.map(d=>`<button class="difficulty ${d.id===state.selectedDifficulty?'active':''}" data-diff="${d.id}"><strong>${d.label}</strong><span>${d.description}</span></button>`).join('')}</div><div class="field" style="margin-top:18px"><label>Prénoms / pseudos — facultatif</label><textarea id="b-people" placeholder="Un prénom ou pseudo par ligne. Répartition automatique et aléatoire."></textarea><div class="muted">Aucune donnée de sexe/genre n’est demandée ou déduite.</div></div><div class="actions" style="margin-top:18px"><button class="btn primary" id="b-create">Créer la partie</button><button class="btn ghost" data-nav="library">Annuler</button></div></section>`);bindNav();const sel=document.getElementById('b-scenario');sel.value=sid;sel.onchange=()=>{const x=byId(sel.value);document.getElementById('b-duration').value=x.durationMin;if(!x.formats.includes('central')&&document.getElementById('b-mode').value==='central')document.getElementById('b-mode').value='team_device'};document.querySelectorAll('[data-diff]').forEach(b=>b.onclick=()=>{state.selectedDifficulty=b.dataset.diff;document.querySelectorAll('[data-diff]').forEach(x=>x.classList.toggle('active',x===b))});document.getElementById('b-create').onclick=()=>{const sc=byId(sel.value),mode=document.getElementById('b-mode').value;if(mode==='central'&&!sc.centralWorlds)return toast('Ce jeu n’a pas de mode TV / salles. Choisis un appareil par équipe.','error');const session=createSession({scenarioId:sc.id,difficulty:state.selectedDifficulty,durationMin:+document.getElementById('b-duration').value,playMode:mode,teamCount:+document.getElementById('b-teams').value,participants:document.getElementById('b-people').value.split(/\n|,/),worldCount:sc.centralWorlds?.length||1,timerMode:document.getElementById('b-timer').value,rotationMode:document.getElementById('b-rotation').value==='yes'});state.session=session;go('session/'+session.id)}}
function host(){if(!hostUnlocked())return hostGate();const sessions=allSessions();app.innerHTML=shell(`<div class="section-title"><div><div class="eyebrow">MODE ANIMATEUR</div><h1>Mes parties</h1></div><div class="actions"><button class="btn primary" id="new-session">Nouvelle partie</button><button class="btn ghost" id="host-lock">Verrouiller</button></div></div>${sessions.length?`<div class="grid cols-2">${sessions.map(s=>{const sc=byId(s.scenarioId);return `<article class="card session-card"><button class="session-open" data-session="${s.id}"><div class="eyebrow">${new Date(s.createdAt).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'})}</div><h2>${esc(sc?.title||'Jeu')}</h2><div class="scenario-meta"><span class="tag">${s.teams.length} équipe(s)</span><span class="tag">${DIFFICULTIES.find(d=>d.id===s.difficulty)?.label}</span><span class="tag">${s.playMode==='central'?'TV / salles':s.playMode==='team_device'?'Appareil / équipe':'Solo'}</span></div></button><div class="actions"><button class="btn small ghost" data-dup="${s.id}">Dupliquer</button><button class="btn small danger" data-del="${s.id}">Supprimer</button></div></article>`}).join('')}</div>`:'<div class="card muted">Aucune partie enregistrée sur cet appareil.</div>'}`);bindNav();document.getElementById('new-session').onclick=()=>sessionBuilder();document.getElementById('host-lock').onclick=()=>{lockHost();go('home')};document.querySelectorAll('[data-session]').forEach(x=>x.onclick=()=>go('session/'+x.dataset.session));document.querySelectorAll('[data-dup]').forEach(b=>b.onclick=()=>{const s=getSession(b.dataset.dup),d=duplicateSession(s);go('session/'+d.id)});document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{if(confirm('Supprimer cette partie et sa progression locale ?')){deleteSession(b.dataset.del);host()}})}
function ensureProgress(s,t,sc){let p=loadProgress(s.id,t.id);if(!p){p=initialProgress(s,t,sc);saveProgress(p)}else if(s.startedAt&&!p.startedAt){p.startedAt=s.startedAt;saveProgress(p)}return p}
function toggleClock(s){if(!s.startedAt){s.startedAt=Date.now();s.pausedAt=null}else if(!s.pausedAt){s.pausedAt=Date.now()}else{s.pausedTotalMs=(s.pausedTotalMs||0)+(Date.now()-s.pausedAt);s.pausedAt=null}saveSession(s)}
function sessionView(id){if(!hostUnlocked()){sessionStorage.setItem('fafaquest-host-next','session/'+id);return go('host-gate')}const s=getSession(id);if(!s)return go('host');const sc=byId(s.scenarioId);state.session=s;const rows=s.teams.map(t=>{const p=ensureProgress(s,t,sc),steps=activeSteps(sc,s.difficulty),max=sc.centralWorlds?.length||steps.length,cur=s.playMode==='central'?p.worldIndex:p.stepIndex,start=sc.centralWorlds?.[t.startWorldIndex||0]?.title;return `<article class="card team-card"><div class="team-head"><div><div class="eyebrow">${esc(t.code)} • signature ${esc(t.teamKey||'01')}</div><h2>${esc(t.name)}</h2>${s.playMode==='central'&&s.rotationMode!==false?`<div class="muted">Départ : ${esc(start||'Monde 1')}</div>`:''}</div><span class="tag">${cur}/${max}</span></div><div class="progressbar"><span style="width:${Math.round(cur/max*100)}%"></span></div><div class="world-track">${Array.from({length:max},(_,i)=>`<span class="world-dot ${i<cur?'done':''}"></span>`).join('')}</div><div class="scenario-meta"><span class="tag">${p.score} pts</span><span class="tag">${p.hintsUsed} aide(s)</span><span class="tag">${t.members.length||'—'} joueur(s)</span></div><div class="actions"><button class="btn small secondary" data-play-team="${t.id}">Ouvrir équipe</button>${s.playMode==='central'?`<button class="btn small primary" data-terminal-team="${t.id}">Terminal</button>`:''}<button class="btn small ghost" data-manage="${t.id}">Gérer</button><button class="btn small ghost" data-team-msg="${t.id}">Message</button><button class="btn small ghost" data-team-skip="${t.id}">Débloquer</button><button class="btn small ghost" data-team-link="${t.id}">Lien autonome</button></div></article>`}).join('');app.innerHTML=shell(`<div class="section-title"><div><div class="eyebrow">TABLEAU ANIMATEUR</div><h1>${esc(sc.title)}</h1></div><div class="timer ${timerClass(sessionRemaining(s))}" id="host-timer">${s.startedAt?fmt(sessionRemaining(s)):'PRÊT'}</div></div><div class="dashboard-grid"><div><div class="teams">${rows}</div></div><aside class="card"><h2>Commandes</h2><div class="host-tools">${s.playMode==='central'?'<button class="btn primary block" id="open-terminal">Terminal central</button><button class="btn secondary block" id="open-tv">Ouvrir écran public</button>':''}<button class="btn primary block" id="clock-toggle">${!s.startedAt?'Démarrer le chrono':s.pausedAt?'Reprendre le chrono':'Mettre en pause'}</button><button class="btn secondary block" id="clock-add">+ 2 minutes</button><button class="btn secondary block" id="guide-host">Guide animateur</button><button class="btn secondary block" id="print-kit">Kit imprimable</button><button class="btn secondary block" id="export-results">Exporter résultats CSV</button><button class="btn ghost block" id="fullscreen">Plein écran</button></div><hr><p class="muted"><strong>Mode :</strong> ${s.playMode==='central'?'TV / salles':s.playMode==='team_device'?'1 appareil / équipe':'Solo'}<br><strong>Niveau :</strong> ${DIFFICULTIES.find(d=>d.id===s.difficulty)?.label}<br><strong>Chrono :</strong> ${s.timerMode==='strict'?'fin stricte':s.timerMode==='loisir'?'indicatif':'animateur décide'}<br><strong>Rotation :</strong> ${s.rotationMode===false?'non':'oui'}</p></aside></div>`,sc);bindNav();clearInterval(ticker);ticker=setInterval(()=>{const e=document.getElementById('host-timer');if(e){const r=sessionRemaining(s);e.textContent=s.startedAt?fmt(r):'PRÊT';e.className='timer '+timerClass(r)}},1000);document.querySelectorAll('[data-play-team]').forEach(b=>b.onclick=()=>launchTeam(s,sc,b.dataset.playTeam));document.querySelectorAll('[data-terminal-team]').forEach(b=>b.onclick=()=>{state.terminalTeamId=b.dataset.terminalTeam;go('terminal/'+s.id)});document.querySelectorAll('[data-manage]').forEach(b=>b.onclick=()=>manageTeam(s,sc,b.dataset.manage));document.querySelectorAll('[data-team-msg]').forEach(b=>b.onclick=()=>{const t=s.teams.find(x=>x.id===b.dataset.teamMsg),p=ensureProgress(s,t,sc),m=prompt('Message pour '+t.name,p.hostMessage||'');if(m!==null){p.hostMessage=m.trim();saveProgress(p);sessionView(s.id)}});document.querySelectorAll('[data-team-skip]').forEach(b=>b.onclick=()=>{const t=s.teams.find(x=>x.id===b.dataset.teamSkip),p=ensureProgress(s,t,sc);if(!confirm('Débloquer manuellement l’étape suivante pour '+t.name+' ?'))return;if(s.playMode==='central')p.worldIndex=Math.min((sc.centralWorlds?.length||1),p.worldIndex+1);else p.stepIndex=Math.min(activeSteps(sc,s.difficulty).length,p.stepIndex+1);saveProgress(p);sessionView(s.id)});document.querySelectorAll('[data-team-link]').forEach(b=>b.onclick=async()=>{const t=s.teams.find(x=>x.id===b.dataset.teamLink),url=makeTeamLink(s,t);await navigator.clipboard?.writeText(url);toast('Lien autonome copié. Il ouvre une copie locale de cette équipe, sans synchronisation live.','success')});document.getElementById('open-terminal')?.addEventListener('click',()=>{state.terminalTeamId=null;go('terminal/'+s.id)});document.getElementById('open-tv')?.addEventListener('click',()=>{const u=new URL(location.href);u.hash='#tv/'+s.id;window.open(u.toString(),'fafaquest-public','popup,width=1280,height=800')});document.getElementById('clock-toggle').onclick=()=>{toggleClock(s);sessionView(s.id)};document.getElementById('clock-add').onclick=()=>{s.durationMin+=2;saveSession(s);sessionView(s.id)};document.getElementById('guide-host').onclick=()=>hostGuide(s,sc);document.getElementById('print-kit').onclick=()=>go('kit/'+s.id);document.getElementById('export-results').onclick=()=>exportResults(s,sc);document.getElementById('fullscreen').onclick=()=>document.documentElement.requestFullscreen?.()}
function manageTeam(session,sc,teamId){const t=session.teams.find(x=>x.id===teamId);const html=`<div class="modal open" id="team-modal" role="dialog" aria-modal="true" aria-labelledby="team-title"><div class="modal-panel" ${theme(sc)}><div class="eyebrow">GESTION ÉQUIPE</div><h1 id="team-title">${esc(t.name)}</h1><div class="field"><label>Nom de l’équipe</label><input id="manage-name" value="${esc(t.name)}"></div><h3>Joueurs et rôles</h3><div class="manage-members">${t.members.length?t.members.map(m=>`<div class="manage-member"><strong>${esc(m)}</strong><select data-role-for="${esc(m)}">${ROLE_LIBRARY.map(r=>`<option value="${r.id}" ${t.roles[m]===r.id?'selected':''}>${esc(r.label)}</option>`).join('')}</select><select data-move-for="${esc(m)}"><option value="">Déplacer vers…</option>${session.teams.filter(x=>x.id!==t.id).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><button class="btn small danger" data-remove-member="${esc(m)}">Retirer</button></div>`).join(''):'<div class="muted">Aucun prénom enregistré.</div>'}</div><div class="field"><label>Ajouter un prénom / pseudo</label><input id="add-member"><button class="btn secondary" id="add-member-go">Ajouter</button></div><div class="actions"><button class="btn primary" id="save-team">Enregistrer</button><button class="btn danger" id="reset-team">Réinitialiser progression</button><button class="btn ghost" id="close-team">Fermer</button></div></div></div>`;document.body.insertAdjacentHTML('beforeend',html);document.querySelectorAll('[data-role-for]').forEach(sel=>sel.onchange=()=>setRole(session,t.id,sel.dataset.roleFor,sel.value));document.querySelectorAll('[data-move-for]').forEach(sel=>sel.onchange=()=>{if(sel.value){moveMember(session,t.id,sel.value,sel.dataset.moveFor);document.getElementById('team-modal').remove();manageTeam(session,sc,t.id)}});document.querySelectorAll('[data-remove-member]').forEach(b=>b.onclick=()=>{removeMember(session,t.id,b.dataset.removeMember);document.getElementById('team-modal').remove();manageTeam(session,sc,t.id)});document.getElementById('add-member-go').onclick=()=>{addMember(session,t.id,document.getElementById('add-member').value);document.getElementById('team-modal').remove();manageTeam(session,sc,t.id)};document.getElementById('save-team').onclick=()=>{renameTeam(session,t.id,document.getElementById('manage-name').value);document.getElementById('team-modal').remove();sessionView(session.id)};document.getElementById('reset-team').onclick=()=>{if(confirm('Réinitialiser toute la progression de cette équipe ?')){storage.remove(`progress:${session.id}:${t.id}`);document.getElementById('team-modal').remove();sessionView(session.id)}};document.getElementById('close-team').onclick=()=>{document.getElementById('team-modal').remove();sessionView(session.id)};document.getElementById('manage-name').focus()}
function hostGuide(session,sc){const html=`<div class="modal open" id="host-modal" role="dialog" aria-modal="true" aria-labelledby="guide-title"><div class="modal-panel" ${theme(sc)}><div class="eyebrow">GUIDE ANIMATEUR</div><h1 id="guide-title">${esc(sc.title)}</h1><h3>Préparation</h3><ol>${(sc.setup||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h3>Matériel</h3><ul>${(sc.materials||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${sc.centralWorlds?`<h3>Mondes / réponses animateur</h3>${sc.centralWorlds.map((w,i)=>`<div class="card host-secret"><strong>${esc(w.title)}</strong><p>${esc(w.hostSetup)}</p><div class="code">BASE : ${esc(w.code)}</div><div class="muted">${(w.props||[]).map(esc).join(' • ')}</div><div class="team-codes">${session.teams.map(t=>`<span class="tag">${esc(t.name)} : ${esc(derivedWorldCode(w,t))}</span>`).join('')}</div></div>`).join('')}`:''}<button class="btn primary block" id="close-guide">Fermer</button></div></div>`;document.body.insertAdjacentHTML('beforeend',html);document.getElementById('close-guide').onclick=()=>document.getElementById('host-modal').remove();document.getElementById('close-guide').focus()}
function exportResults(s,sc){const rows=[['Équipe','Progression','Score','Aides','Terminée']];for(const t of s.teams){const p=ensureProgress(s,t,sc);rows.push([t.name,s.playMode==='central'?p.worldIndex:p.stepIndex,p.score,p.hintsUsed,p.finishedAt?'oui':'non'])}const csv=rows.map(r=>r.map(x=>`"${String(x).replace(/"/g,'""')}"`).join(';')).join('\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`fafa-quest-${sc.id}-resultats.csv`;a.click();URL.revokeObjectURL(a.href)}
function printableVisual(p){const t=p.template||'';let visual='';if(t==='tangram')visual=`<div class="print-visual"><svg class="tangram-svg" viewBox="0 0 200 200" aria-label="Tangram à découper"><polygon points="0,0 100,100 200,0" fill="#ff4f8b"/><polygon points="0,0 0,200 100,100" fill="#8d3a7b"/><polygon points="0,200 100,100 100,200" fill="#ff9138"/><polygon points="100,100 150,50 150,150" fill="#ffe44f"/><polygon points="150,50 200,0 200,100" fill="#40dbe4"/><polygon points="100,100 150,150 100,200 50,150" fill="#4f75ff"/><polygon points="100,200 150,150 200,100 200,200" fill="#54d96a"/></svg><p class="print-note">Découper les 7 formes. En mode physique, écrire le mot <strong>LA</strong> au dos lorsque l’assemblage est correct.</p></div>`;else if(t==='mastermind-duo')visual=`<div class="print-visual"><div class="puzzle-sheet"><h4>VERROU CHIFFRES</h4><p><b>4635</b> — 1 chiffre bon et bien placé</p><p><b>2807</b> — 2 bons mais mal placés</p><p><b>4159</b> — 1 bon mais mal placé</p><p><b>3789</b> — rien n’est bon</p><p><b>7452</b> — 1 bon et bien placé</p><div class="answer-box">_ _ _ _</div><hr><h4>VERROU COULEURS</h4><div class="color-lock-row"><i style="--c:#8b3b13"></i><i style="--c:#ed3440"></i><i style="--c:#4b7ef6"></i><span>2 bonnes, mal placées</span></div><div class="color-lock-row"><i style="--c:#ffe93d"></i><i style="--c:#ed3440"></i><i style="--c:#111"></i><span>2 bonnes, 1 bien placée</span></div><div class="color-lock-row"><i style="--c:#111"></i><i style="--c:#3b9b48"></i><i style="--c:#4b7ef6"></i><span>2 bonnes, mal placées</span></div><div class="color-lock-row"><i style="--c:#3b9b48"></i><i style="--c:#ffe93d"></i><i style="--c:#bbb"></i><span>aucune correcte</span></div></div></div>`;else if(t==='letter-cards')visual=`<div class="print-visual card-cut-grid"><div class="cut-card">E</div><div class="cut-card">S</div><div class="cut-card">T</div><div class="cut-card decoy">?</div><div class="cut-card decoy">×</div></div>`;else if(t==='stencil')visual=`<div class="print-visual"><div class="stencil-support">Q Z <b>L</b> X R T <b>A</b> M P</div><div class="stencil-mask"><span>✂ MASQUE À DÉCOUPER</span><div class="holes"><i></i><i></i></div></div><p class="print-note">Découper les deux fenêtres du masque puis l’aligner sur le support pour révéler <strong>LA</strong>.</p></div>`;else if(t==='fold')visual=`<div class="print-visual fold-sheet"><div>PLI 1<br><b>Objet qui ouvre un verrou</b></div><div>PLI 2<br><b>USB, plate ou anglaise</b></div><div>PLI 3<br><b>Mot de 3 lettres</b></div></div>`;else if(t==='red-filter'||t==='red-filter-code')visual=`<div class="print-visual"><div class="camouflage-card"><span class="hidden-cyan">${t==='red-filter'?'NAPPE':'1234'}</span>${Array.from({length:16},(_,i)=>`<span class="noise" style="left:${(i*17)%92}%;top:${(i*29)%88}%">${'Q7RXM2'[i%6]}</span>`).join('')}</div><p class="print-note">Imprimer en couleur et utiliser un calque rouge transparent. Tester le rendu avant l’animation : les imprimantes et filtres peuvent modifier l’effet.</p></div>`;else if(t==='final-key')visual=`<div class="print-visual card-cut-grid words"><div class="cut-card">LA</div><div class="cut-card">CLÉ</div><div class="cut-card">EST</div><div class="cut-card">SOUS</div><div class="cut-card">LA</div><div class="cut-card">NAPPE</div></div>`;else if(t==='mirror')visual=`<div class="print-visual"><div class="mirror-text">LE CANOT ATTEND AU PONT C</div><p class="print-note">À lire avec un miroir.</p></div>`;else if(t==='uv')visual=`<div class="print-visual uv-card"><h4>DOSSIER TECHNIQUE</h4><p>Zone UV : __________________</p><p class="print-note">Après impression, écrire <strong>854</strong> au stylo UV dans la zone.</p></div>`;else if(t==='balloon-key')visual=`<div class="print-visual card-cut-grid"><div class="cut-card">ÉQUIPE 01<br>CLÉ</div><div class="cut-card">ÉQUIPE 02<br>CLÉ</div><div class="cut-card">ÉQUIPE 03<br>CLÉ</div><div class="cut-card">ÉQUIPE 04<br>CLÉ</div></div>`;else if(t==='timeline')visual=`<div class="print-visual timeline"><div>PRÉHISTOIRE</div><div>ANTIQUITÉ</div><div>MOYEN ÂGE</div><div>ÉPOQUE MODERNE</div><div>ÉPOQUE CONTEMPORAINE</div></div>`;else if(t==='era-map')visual=`<div class="print-visual era-map"><span>VILLAGE</span><b>→</b><span>CAVERNE</span><b>→</b><span>MONTAGNE</span><b>→</b><span>LAC</span><b>→</b><span>CABANE</span><b>→</b><span>CHÂTEAU</span></div>`;else if(t==='symbol-cards')visual=`<div class="print-visual card-cut-grid"><div class="cut-card">▲ 5</div><div class="cut-card">◆ 8</div><div class="cut-card">● 9</div><div class="cut-card">⬟ 4</div><div class="cut-card">✦ 7</div></div>`;else if(t==='fake-phone-cards')visual=`<div class="print-visual phone-cards"><div class="phone-card"><b>STORY — 20:14</b><p>Photo de groupe publiée.</p></div><div class="phone-card"><b>DM — 20:18</b><p>« Je préfère que tu retires la photo, stp. »</p></div><div class="phone-card"><b>GROUPE — 20:26</b><p>Capture repartagée dans une autre conversation.</p></div></div>`;else if(t==='diffusion-chain')visual=`<div class="print-visual diffusion-chain"><span>PHOTO</span><b>→</b><span>STORY</span><b>→</b><span>CAPTURE</span><b>→</b><span>AUTRE GROUPE</span></div>`;else if(t==='station-motion')visual=`<div class="print-visual station"><h3>STATION MOUVEMENT</h3><p>Défi moteur adaptable par l’animateur.</p><strong>Validation : PULSE</strong></div>`;else if(t==='station-maths')visual=`<div class="print-visual card-cut-grid"><div class="cut-card">120 m<br>30 s</div><div class="cut-card">200 m<br>50 s</div><div class="cut-card">80 m<br>20 s</div><div class="cut-card">160 m<br>40 s</div></div>`;else if(t==='station-science')visual=`<div class="print-visual card-cut-grid"><div class="cut-card">3</div><div class="cut-card">4</div><div class="cut-card">2</div><div class="cut-card">5</div></div>`;return `<article class="print-card printable-template"><div class="eyebrow">${esc(p.kind||'Préparer')}</div><h3>${esc(p.title)}</h3><p>${esc(p.body)}</p>${visual}</article>`}
function printKit(id){if(!hostUnlocked()){sessionStorage.setItem('fafaquest-host-next','kit/'+id);return go('host-gate')}const s=getSession(id);if(!s)return go('host');const sc=byId(s.scenarioId);app.innerHTML=`<main class="print-kit"><div class="print-actions no-print"><button class="btn primary" id="kit-print">Imprimer / PDF</button><button class="btn secondary" id="kit-back">Retour animateur</button></div><section class="print-page"><h1>FAFA QUEST — ${esc(sc.title)}</h1><p><strong>Niveau :</strong> ${esc(DIFFICULTIES.find(d=>d.id===s.difficulty)?.label)} • <strong>Durée :</strong> ${s.durationMin} min • <strong>Équipes :</strong> ${s.teams.length}</p><h2>Plan animateur</h2><ol>${(sc.setup||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h2>Matériel</h2><ul>${(sc.materials||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="print-page"><h2>Cartes équipes</h2><div class="print-team-grid">${s.teams.map(t=>`<article class="print-card"><h3>${esc(t.name)}</h3><p>Code local : <strong>${esc(t.code)}</strong></p><p>Signature d’équipe : <strong>${esc(t.teamKey)}</strong></p>${s.playMode==='central'&&sc.centralWorlds?`<p>Départ : <strong>${esc(sc.centralWorlds[t.startWorldIndex||0]?.title)}</strong></p>`:''}<p>${t.members.map(esc).join(' • ')||'Joueurs à compléter'}</p></article>`).join('')}</div></section>${sc.centralWorlds?`<section class="print-page"><h2>Fiches mondes — animateur</h2>${sc.centralWorlds.map(w=>`<article class="print-card"><h3>${esc(w.title)}</h3><p>${esc(w.hostSetup)}</p><p><strong>Code de base : ${esc(w.code)}</strong></p><p>${(w.props||[]).map(esc).join(' • ')}</p><div>${s.teams.map(t=>`<span>${esc(t.name)} → <strong>${esc(derivedWorldCode(w,t))}</strong><br></span>`).join('')}</div></article>`).join('')}</section>`:''}${sc.printables?.length?`<section class="print-page"><h2>Kit papier / objets à préparer</h2><div class="print-team-grid">${sc.printables.map(printableVisual).join('')}</div></section>`:''}<section class="print-page"><h2>Rôles</h2><div class="print-team-grid">${ROLE_LIBRARY.map(r=>`<article class="print-card"><h3>${esc(r.label)}</h3><p>${esc(r.mission)}</p></article>`).join('')}</div></section></main>`;document.getElementById('kit-print').onclick=()=>window.print();document.getElementById('kit-back').onclick=()=>go('session/'+s.id)}
function testScenario(id){if(!hostUnlocked()){sessionStorage.setItem('fafaquest-host-next','test/'+id);return go('host-gate')}const s=byId(id);if(!s)return go('library');app.innerHTML=shell(`<div class="section-title"><div><div class="eyebrow">MODE TEST ANIMATEUR</div><h1>${esc(s.title)}</h1></div><button class="btn secondary" data-nav="scenario/${s.id}">Retour fiche</button></div>${DIFFICULTIES.map(d=>`<section class="card test-level"><h2>${esc(d.label)} — ${activeSteps(s,d.id).length} épreuves</h2>${activeSteps(s,d.id).map((st,i)=>`<details class="test-step"><summary>${i+1}. ${esc(st.title)} <span class="tag">${esc(st.type)}</span></summary><p>${esc(st.prompt)}</p><div class="host-secret"><strong>Réponse :</strong> ${esc(Array.isArray(st.answer)?st.answer.join(' → '):st.answer)}</div><p class="muted">Aide 1 : ${esc(st.hints?.[0]||'—')}<br>Solution / aide forte : ${esc(st.hints?.[1]||'—')}</p></details>`).join('')}</section>`).join('')}`,s);bindNav()}

function launchTeam(s,sc,teamId){const t=s.teams.find(x=>x.id===teamId);if(!t)return;state.session=s;state.scenario=sc;state.team=t;state.progress=ensureProgress(s,t,sc);if(!s.startedAt&&s.playMode!=='central'){s.startedAt=Date.now();saveSession(s);state.progress.startedAt=s.startedAt;saveProgress(state.progress)}go('play')}
function join(){app.innerHTML=shell(`<section class="card auth-card"><div class="eyebrow">OUVERTURE LOCALE</div><h1>Code d’équipe sur cet appareil</h1><p class="muted">Ce champ retrouve uniquement les parties créées sur ce même appareil. Pour jouer sur un autre téléphone, demande à l’animateur le <strong>lien autonome de ton équipe</strong>. Ce lien ne synchronise pas la progression en direct.</p><div class="field"><label>Code d’équipe</label><input id="join-code" maxlength="6" autocomplete="off"></div><button class="btn primary block" id="join-go" style="margin-top:14px">Ouvrir</button></section>`);bindNav();document.getElementById('join-go').onclick=()=>{const f=findTeamByCode(document.getElementById('join-code').value);if(!f)return toast('Code introuvable sur cet appareil.','error');launchTeam(f.session,byId(f.session.scenarioId),f.team)}}
function playerIntro(){const s=state.scenario,p=state.progress,t=state.team;app.innerHTML=shell(`<div class="game-shell intro-screen"><section class="card intro-card"><div class="scenario-big-icon">${esc(s.icon)}</div><div class="eyebrow">${esc(t.name)} • ${esc(genreLabel(s))}</div><h1>${esc(s.title)}</h1><p>${esc(s.intro)}</p><div class="scenario-meta"><span class="tag">${esc(DIFFICULTIES.find(d=>d.id===state.session.difficulty)?.label)}</span><span class="tag">${activeSteps(s,state.session.difficulty).length} épreuves</span><span class="tag">${state.session.durationMin} min</span></div><button class="btn primary block" id="intro-start">3… 2… 1… LANCER LA MISSION</button></section></div>`,s,{player:true});bindNav();document.getElementById('intro-start').onclick=()=>{p.introSeen=true;if(!state.session.startedAt){state.session.startedAt=Date.now();saveSession(state.session);p.startedAt=state.session.startedAt}saveProgress(p);play()}}
function chapterTransition(chapter){const p=state.progress,s=state.scenario;p.seenChapters=p.seenChapters||[];app.innerHTML=shell(`<div class="game-shell chapter-transition"><section class="card intro-card"><div class="portal-ring">${esc(s.icon)}</div><div class="eyebrow">NOUVEAU CHAPITRE</div><h1>${esc(chapter.title)}</h1><p>Le décor change. Prenez quelques secondes pour répartir les rôles et observer avant d’agir.</p><button class="btn primary block" id="chapter-go">Entrer</button></section></div>`,s,{player:true});bindNav();document.getElementById('chapter-go').onclick=()=>{p.seenChapters.push(chapter.id);saveProgress(p);play()}}
function timeUp(){const s=state.scenario;app.innerHTML=shell(`<div class="game-shell"><section class="card time-up"><div class="eyebrow">TEMPS ÉCOULÉ</div><h1>La mission est en pause.</h1><p>Le mode de cette partie impose une fin stricte. L’animateur peut ajouter du temps ou débloquer la suite depuis son tableau.</p><button class="btn secondary block" data-nav="home">Quitter</button></section></div>`,s,{player:true});bindNav()}
function renderRoles(){const t=state.team;if(!t.members.length)return '<div class="muted">Sans prénoms enregistrés : répartissez librement les rôles Observateur, Décodeur, Messager et Gardien du temps.</div>';return `<div class="role-grid">${t.members.map(m=>{const r=ROLE_LIBRARY.find(x=>x.id===t.roles[m]);return `<div class="role-card"><strong>${esc(m)} — ${esc(r?.label||'Explorateur')}</strong><div class="muted">${esc(r?.mission||'')}</div></div>`}).join('')}</div>`}
function renderEvidence(st){if(!st.evidence?.length)return'';return `<div class="evidence-panel"><div class="evidence-title">DOSSIER / ÉLÉMENTS À ANALYSER</div>${st.evidence.map(e=>`<div class="evidence ${esc(e.kind||'note')}">${e.kind==='stamp'?'<div class="stamp-badge">TOP SECRET</div>':''}<div class="evidence-head"><strong>${esc(e.author||'Élément')}</strong><span>${esc(e.time||'')}</span></div><div class="evidence-text">${esc(e.text||'')}</div>${e.meta?`<div class="evidence-meta">${esc(e.meta)}</div>`:''}</div>`).join('')}</div>`}
function keypad(){return `<div class="keypad">${['1','2','3','4','5','6','7','8','9','C','0','⌫'].map(k=>`<button class="btn secondary" data-key="${k}">${k}</button>`).join('')}</div>`}
function colorCss(c){return {rouge:'#e64a55',bleu:'#4f8cff',noir:'#171717',jaune:'#ffd84a',vert:'#55cc77',orange:'#ff9d4a',violet:'#a970ff'}[c]||c}
function stepInput(st){if(st.type==='choice')return `<div class="option-list">${st.options.map((o,i)=>`<button class="option" data-choice="${i}">${esc(o)}</button>`).join('')}</div>`;if(['text','team_split','cipher'].includes(st.type))return `${st.type==='team_split'?`<div class="role-grid">${Object.entries(st.cards||{}).filter(([k])=>k!=='default').map(([k,v])=>`<div class="role-card"><strong>${esc(ROLE_LIBRARY.find(r=>r.id===k)?.label||k)}</strong><div>${esc(v)}</div></div>`).join('')}</div>`:''}${st.type==='cipher'&&st.cipherMode==='caesar'?`<div class="cipher-helper"><strong>Roue de César</strong><p class="muted">Décalage : <input id="cipher-shift" type="range" min="1" max="25" value="3"> <span id="cipher-shift-v">3</span></p></div>`:''}<div class="field"><label>Réponse de l’équipe</label><input id="answer-text" autocomplete="off" placeholder="Votre réponse"></div><button class="btn primary" id="submit-text">Valider</button>`;if(st.type==='keypad')return `<div class="key-display" id="play-key-display">—</div>${keypad()}<button class="btn primary block" id="submit-key">Valider le code</button>`;if(st.type==='multi')return `<div class="option-list">${st.options.map(o=>`<label class="option"><input type="checkbox" value="${esc(o.id)}"> <span>${esc(o.label)}</span></label>`).join('')}</div><button class="btn primary" id="submit-multi">Valider</button>`;if(st.type==='file_hunt')return `<div class="file-explorer"><div class="file-bar">▣ DOSSIER NUMÉRIQUE</div>${st.entries.map(e=>`<label class="file-row"><input type="checkbox" value="${esc(e.id)}"><span class="file-icon">${e.name.endsWith('.png')||e.name.endsWith('.jpg')?'▧':e.name.endsWith('.mp4')?'▶':'▤'}</span><span><strong>${esc(e.name)}</strong><small>${esc(e.path||'')}</small></span></label>`).join('')}</div><button class="btn primary" id="submit-file-hunt">Valider la sélection</button>`;if(st.type==='order')return `<p class="muted">Touchez les éléments dans le bon ordre.</p><div class="option-list">${(st.items||[]).map(o=>`<button class="option" data-order="${esc(o)}">${esc(o)}</button>`).join('')}</div><div class="sequence-line" id="order-line"></div><div class="actions"><button class="btn primary" id="submit-order">Valider l’ordre</button><button class="btn ghost" id="reset-order">Recommencer</button></div>`;if(st.type==='color_code')return `<p class="muted">Touchez les couleurs dans l’ordre. Le nom reste affiché pour ne pas dépendre uniquement de la couleur.</p><div class="color-palette">${st.tokens.map(c=>`<button class="color-token" data-color="${c}" aria-label="${c}" style="--swatch:${colorCss(c)}"><span>${esc(c)}</span></button>`).join('')}</div><div class="sequence-line" id="color-line"></div><div class="actions"><button class="btn primary" id="submit-color">Valider</button><button class="btn ghost" id="reset-color">Recommencer</button></div>`;if(st.type==='memory')return `<div class="memory-stage" id="memory-stage"><button class="btn secondary" id="memory-show">Mémoriser la séquence (${Math.round((st.memoryMs||5000)/1000)} s)</button></div><div class="option-list">${st.tokens.map(x=>`<button class="option" data-memory="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="sequence-line" id="memory-line"></div><div class="actions"><button class="btn primary" id="submit-memory">Valider</button><button class="btn ghost" id="reset-memory">Recommencer</button></div>`;if(st.type==='sound')return `<div class="sound-panel"><button class="btn primary" id="play-tones">▶ Écouter les sons</button><details><summary>Alternative accessible</summary><p class="muted">Fréquences : ${(st.tones||[]).join(' Hz • ')} Hz. L’objectif est de comparer leur hauteur, pas de reconnaître une musique.</p></details></div><div class="option-list">${st.options.map(o=>`<button class="option" data-sound-answer="${esc(o)}">Son ${esc(o)}</button>`).join('')}</div>`;if(st.type==='match')return `<div class="pair-grid">${st.pairs.map((p,i)=>`<div class="pair-row"><strong>${esc(p[0])}</strong><select data-pair="${i}"><option value="">— choisir —</option>${st.pairs.map(x=>`<option>${esc(x[1])}</option>`).join('')}</select></div>`).join('')}</div><button class="btn primary" id="submit-match" style="margin-top:12px">Valider les associations</button>`;if(st.type==='physical')return `<div class="feedback ok"><strong>Épreuve physique / réelle</strong><br>${esc(st.physicalLabel||'Manipulation / fouille')} — réalisez l’action dans la zone préparée.</div><div class="field"><label>Mot de validation trouvé ou donné par l’animateur</label><input id="physical-answer" placeholder="Mot de validation"></div><button class="btn primary" id="submit-physical">Valider</button>`;if(st.type==='reveal')return `<div class="reveal-lab ${esc(st.revealMode||'')}"><div class="reveal-stage" id="reveal-stage">Commencez la manipulation.</div><div class="actions">${(st.stages||[]).map((x,i)=>`<button class="btn secondary" data-reveal="${i}">${esc(x.label)}</button>`).join('')}</div></div><div class="field"><label>Réponse révélée</label><input id="reveal-answer" autocomplete="off"></div><button class="btn primary" id="submit-reveal">Valider</button>`;if(st.type==='hotspot')return `<div class="hotspot-scene">${(st.spots||[]).map(x=>`<button class="hotspot-item" data-hotspot="${esc(x.id)}"><span>${esc(x.label)}</span></button>`).join('')}</div><div class="found-fragments" id="found-fragments">Aucun fragment trouvé.</div><div class="field"><label>Réponse finale</label><input id="hotspot-answer" autocomplete="off"></div><button class="btn primary" id="submit-hotspot">Valider</button>`;if(st.type==='lock_parts')return `<div class="lock-parts">${(st.fields||[]).map((x,i)=>`<div class="field"><label>${esc(x)}</label><input data-lock-part="${i}" autocomplete="off"></div>`).join('')}</div><button class="btn primary" id="submit-lock-parts">Ouvrir le verrou</button>`;return '<button class="btn primary" id="submit-manual">Valider</button>'}
function wireStep(st){document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>submit(st,+b.dataset.choice));document.getElementById('submit-text')?.addEventListener('click',()=>submit(st,document.getElementById('answer-text').value));document.getElementById('cipher-shift')?.addEventListener('input',e=>{const v=document.getElementById('cipher-shift-v');if(v)v.textContent=e.target.value});let kv='';document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{const k=b.dataset.key;if(k==='C')kv='';else if(k==='⌫')kv=kv.slice(0,-1);else kv+=k;const d=document.getElementById('play-key-display');if(d)d.textContent=kv||'—'});document.getElementById('submit-key')?.addEventListener('click',()=>submit(st,kv));document.getElementById('submit-multi')?.addEventListener('click',()=>submit(st,[...document.querySelectorAll('.option input:checked')].map(x=>x.value)));document.getElementById('submit-file-hunt')?.addEventListener('click',()=>submit(st,[...document.querySelectorAll('.file-row input:checked')].map(x=>x.value)));let order=[];const resetOrder=()=>{order=[];document.querySelectorAll('[data-order]').forEach(x=>x.classList.remove('selected'));const l=document.getElementById('order-line');if(l)l.innerHTML=''};document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{if(order.includes(b.dataset.order))return;order.push(b.dataset.order);b.classList.add('selected');document.getElementById('order-line').innerHTML=order.map(x=>`<span class="sequence-chip">${esc(x)}</span>`).join('')});document.getElementById('submit-order')?.addEventListener('click',()=>submit(st,order));document.getElementById('reset-order')?.addEventListener('click',resetOrder);let colors=[];const resetColor=()=>{colors=[];document.querySelectorAll('[data-color]').forEach(x=>x.classList.remove('selected'));document.getElementById('color-line').innerHTML=''};document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{colors.push(b.dataset.color);b.classList.add('selected');document.getElementById('color-line').innerHTML=colors.map(x=>`<span class="sequence-chip">${esc(x)}</span>`).join('')});document.getElementById('submit-color')?.addEventListener('click',()=>submit(st,colors));document.getElementById('reset-color')?.addEventListener('click',resetColor);let mem=[];const resetMemory=()=>{mem=[];document.getElementById('memory-line').innerHTML=''};document.getElementById('memory-show')?.addEventListener('click',()=>{const stage=document.getElementById('memory-stage');stage.innerHTML=`<div class="memory-tokens">${st.sequence.map(x=>`<span>${esc(x)}</span>`).join(' → ')}</div>`;setTimeout(()=>stage.innerHTML='<strong>Séquence masquée.</strong>',st.memoryMs||5000)});document.querySelectorAll('[data-memory]').forEach(b=>b.onclick=()=>{mem.push(b.dataset.memory);document.getElementById('memory-line').innerHTML=mem.map(x=>`<span class="sequence-chip">${esc(x)}</span>`).join('')});document.getElementById('submit-memory')?.addEventListener('click',()=>submit(st,mem));document.getElementById('reset-memory')?.addEventListener('click',resetMemory);document.getElementById('play-tones')?.addEventListener('click',()=>playTones(st.tones||[]));document.querySelectorAll('[data-sound-answer]').forEach(b=>b.onclick=()=>submit(st,b.dataset.soundAnswer));document.getElementById('submit-match')?.addEventListener('click',()=>{const vals=[...document.querySelectorAll('[data-pair]')].map((x,i)=>x.value===st.pairs[i][1]);submit(st,vals.every(Boolean)?'ok':'bad')});document.getElementById('submit-physical')?.addEventListener('click',()=>submit(st,document.getElementById('physical-answer').value));document.querySelectorAll('[data-reveal]').forEach(b=>b.onclick=()=>{const x=st.stages?.[+b.dataset.reveal];const stage=document.getElementById('reveal-stage');if(stage&&x){stage.innerHTML=`<strong>${esc(x.label)}</strong><div>${esc(x.content)}</div>`;b.classList.add('selected')}});document.getElementById('submit-reveal')?.addEventListener('click',()=>submit(st,document.getElementById('reveal-answer').value));let found=[];document.querySelectorAll('[data-hotspot]').forEach(b=>b.onclick=()=>{const sp=st.spots?.find(x=>x.id===b.dataset.hotspot);if(!sp)return;b.classList.add(sp.correct?'found':'decoy');if(sp.correct&&!found.includes(sp.id))found.push(sp.id);const box=document.getElementById('found-fragments');if(box)box.innerHTML=found.length?`Fragments : ${found.map(id=>esc(st.spots.find(x=>x.id===id)?.fragment||id)).join(' • ')}`:'Aucun fragment trouvé.'});document.getElementById('submit-hotspot')?.addEventListener('click',()=>{const req=st.required||[];if(req.length&&!req.every(id=>found.includes(id)))return toast('Il reste des éléments utiles à trouver dans la zone.','error');submit(st,document.getElementById('hotspot-answer').value)});document.getElementById('submit-lock-parts')?.addEventListener('click',()=>submit(st,[...document.querySelectorAll('[data-lock-part]')].map(x=>x.value)));document.querySelectorAll('[data-hint-kind]').forEach(b=>b.onclick=()=>{const diff=DIFFICULTIES.find(d=>d.id===state.session.difficulty);if(state.progress.hintsUsed>=diff.hintBudget)return toast('Budget d’aides épuisé pour ce niveau.','error');const kind=b.dataset.hintKind;if(kind==='solution'&&!solutionAvailable(state.progress,state.session.difficulty))return;state.hint=useHint(state.progress,st,kind);play()})}
function playTones(tones){try{const C=window.AudioContext||window.webkitAudioContext,c=new C();tones.forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain();o.frequency.value=f;g.gain.value=.04;o.connect(g);g.connect(c.destination);o.start(c.currentTime+i*.5);o.stop(c.currentTime+i*.5+.28)});setTimeout(()=>c.close(),tones.length*500+500)}catch{}}
function recap(){const r=state.recap,s=state.scenario;app.innerHTML=shell(`<div class="game-shell"><section class="card recap-card"><div class="eyebrow">REPÈRE À RETENIR</div><h1>Bien vu.</h1><p>${esc(r.fact)}</p>${r.source?`<div class="source-note">Source / repère : ${esc(r.source)}</div>`:''}<button class="btn primary block" id="recap-go">Continuer</button></section></div>`,s,{player:true});bindNav();document.getElementById('recap-go').onclick=()=>{state.recap=null;state.feedback=null;play()}}
function finale(){const s=state.scenario,p=state.progress,steps=activeSteps(s,state.session.difficulty);app.innerHTML=shell(`<div class="game-shell"><section class="card finale-card"><div class="eyebrow">MISSION ACCOMPLIE</div><div class="final-star">★</div><h1>${esc(state.team.name)}</h1><p>${esc(s.finale)}</p><div class="metric-row">${metric('Score',p.score)}${metric('Aides',p.hintsUsed)}${metric('Temps',fmt(playerElapsed(p,state.session)))}${metric('Épreuves',p.completedSteps.length+'/'+steps.length)}</div>${s.debrief?`<div class="debrief"><h3>Débrief avec l’animateur</h3><ul>${s.debrief.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<button class="btn primary block" data-nav="home">Terminer</button></section></div>`,s,{player:true});bindNav()}
function terminal(id){if(!hostUnlocked()){sessionStorage.setItem('fafaquest-host-next','terminal/'+id);return go('host-gate')}const s=getSession(id);if(!s)return go('host');const sc=byId(s.scenarioId);if(!sc.centralWorlds)return go('session/'+id);if(isStrictTimeUp(s)){app.innerHTML=`<main class="terminal-shell" ${theme(sc)}><section class="terminal-card time-up"><div class="eyebrow">TEMPS ÉCOULÉ</div><h1>Terminal verrouillé</h1><p>L’animateur doit ajouter du temps ou changer le mode de la partie.</p><button class="btn secondary" id="term-time-host">Retour animateur</button></section></main>`;document.getElementById('term-time-host').onclick=()=>go('session/'+id);return}let team=state.terminalTeamId?s.teams.find(x=>x.id===state.terminalTeamId):null;if(!team){app.innerHTML=`${topbar()}<main class="terminal-shell" ${theme(sc)}><section class="terminal-card"><div class="eyebrow">TERMINAL CENTRAL</div><h1>${esc(sc.title)}</h1><p>Choisissez l’équipe qui revient de sa salle.</p><div class="grid cols-2">${s.teams.map(t=>`<button class="btn secondary terminal-team" data-term-select="${t.id}">${esc(t.name)}<br><span class="code">signature ${esc(t.teamKey)}</span></button>`).join('')}</div><button class="btn ghost" id="term-back">Retour animateur</button></section></main>`;bindNav();document.querySelectorAll('[data-term-select]').forEach(b=>b.onclick=()=>{state.terminalTeamId=b.dataset.termSelect;terminal(id)});document.getElementById('term-back').onclick=()=>go('session/'+id);return}const p=ensureProgress(s,team,sc);if(p.worldIndex>=sc.centralWorlds.length)return terminalFinal(s,sc,team,p);const wi=currentWorldIndex(s,team,p,sc.centralWorlds.length),w=sc.centralWorlds[wi];app.innerHTML=`<main class="terminal-shell" ${theme(sc)}><section class="terminal-card world-${wi}"><div class="eyebrow">${esc(team.name)} • MONDE ${p.worldIndex+1}/${sc.centralWorlds.length}</div><div class="terminal-world-icon">${esc(w.icon)}</div><h1>${esc(w.title)}</h1><p>${esc(w.brief)}</p><div class="team-signature"><strong>Signature d’équipe : ${esc(team.teamKey)}</strong><br><span>Ajoutez cette signature à la fin du code trouvé dans la salle.</span></div>${p.hostMessage?`<div class="hintbox"><strong>Message animateur</strong><br>${esc(p.hostMessage)}</div>`:''}<div class="key-display" id="term-display">—</div>${w.codeType==='digits'?keypad():''}<div class="field terminal-input"><label>Code final de l’équipe</label><input id="term-input" autocomplete="off" placeholder="Ex. code trouvé + signature" style="text-align:center;text-transform:uppercase"></div><div class="actions centered"><button class="btn primary" id="term-submit">VALIDER LE CODE</button><button class="btn ghost" id="term-switch">Changer d’équipe</button><button class="btn ghost" id="term-host">Animateur</button></div></section></main>`;let val='';const input=document.getElementById('term-input'),disp=document.getElementById('term-display');document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{const k=b.dataset.key;if(k==='C')val='';else if(k==='⌫')val=val.slice(0,-1);else val+=k;input.value=val;disp.textContent=val||'—'});input.oninput=()=>{val=input.value;disp.textContent=val||'—'};document.getElementById('term-submit').onclick=()=>{if(validateWorldCode(w,team,input.value)){sound(true);p.worldIndex++;p.score+=200;saveProgress(p);announce('Code correct');app.innerHTML=`<main class="terminal-shell" ${theme(sc)}><section class="terminal-card transition-success"><div class="eyebrow">CODE VALIDÉ</div><div class="terminal-world-icon">✓</div><h1>${esc(w.success)}</h1><p>${p.worldIndex<sc.centralWorlds.length?'Le portail suivant est maintenant accessible.':'Vous avez franchi le dernier verrou.'}</p><button class="btn primary" id="term-next">Continuer</button></section></main>`;document.getElementById('term-next').onclick=()=>terminal(id)}else{sound(false);toast('Code incorrect. Vérifiez le code de salle ET la signature de votre équipe.','error')}};document.getElementById('term-switch').onclick=()=>{state.terminalTeamId=null;terminal(id)};document.getElementById('term-host').onclick=()=>go('session/'+id)}
function terminalFinal(s,sc,t,p){if(!p.finishedAt)finish(p);app.innerHTML=`<main class="terminal-shell" ${theme(sc)}><section class="terminal-card finale-card"><div class="eyebrow">TOUS LES MONDES DÉVERROUILLÉS</div><div class="final-star">★</div><h1>${esc(t.name)}</h1><p>${esc(sc.finale)}</p><div class="metric-row">${metric('Score',p.score)}${metric('Mondes',sc.centralWorlds.length)}${metric('Temps',fmt(playerElapsed(p,s)))}${metric('Équipe',t.members.length||'—')}</div><div class="actions centered"><button class="btn primary" id="final-switch">Équipe suivante</button><button class="btn secondary" id="final-host">Animateur</button></div></section></main>`;document.getElementById('final-switch').onclick=()=>{state.terminalTeamId=null;terminal(s.id)};document.getElementById('final-host').onclick=()=>go('session/'+s.id)}
function tv(id){const s=getSession(id);if(!s)return go('home');const sc=byId(s.scenarioId);function draw(){const rem=sessionRemaining(s);app.innerHTML=`<main class="tv-shell" ${theme(sc)}><div class="tv-title"><div class="eyebrow">FAFA QUEST • ÉCRAN PUBLIC</div><h1>${esc(sc.title)}</h1></div><div class="tv-timer ${timerClass(rem)}" id="tv-time">${s.startedAt?fmt(rem):'PRÊT'}</div><div class="tv-teams">${s.teams.map(t=>{const p=ensureProgress(s,t,sc),max=sc.centralWorlds?.length||activeSteps(sc,s.difficulty).length,cur=s.playMode==='central'?p.worldIndex:p.stepIndex;return `<div class="tv-team"><strong>${esc(t.name)}</strong><div class="progressbar"><span style="width:${Math.round(cur/max*100)}%"></span></div><span>${cur}/${max} • ${p.score} pts</span></div>`}).join('')}</div><button class="btn ghost no-project" id="tv-full">Plein écran</button></main>`;document.getElementById('tv-full').onclick=()=>document.documentElement.requestFullscreen?.()}draw();clearInterval(ticker);ticker=setInterval(()=>{const e=document.getElementById('tv-time');if(e){const r=sessionRemaining(s);e.textContent=s.startedAt?fmt(r):'PRÊT';e.className='tv-timer '+timerClass(r)}},1000)}
function about(){app.innerHTML=shell(`<section class="card"><h1>FAFA QUEST</h1><p>Application séparée d’Explor’Action. La v0.5 regroupe joueur et animateur sur GitHub Pages, avec un mode TV / salles, un outil de préparation, des niveaux différenciés et un monde Questions d’ados.</p><p class="muted">Le lien autonome permet d’ouvrir une copie locale d’équipe sur un autre téléphone, mais la synchronisation live entre appareils nécessite toujours un backend temps réel.</p></section>`);bindNav()}
function render(){clearInterval(ticker);const h=location.hash.replace(/^#/,'')||'home';if(h==='home')return home();if(h==='library')return library();if(h==='ado')return adoWorld();if(h==='recommend')return recommend();if(h==='host-gate')return hostGate();if(h==='host')return host();if(h.startsWith('build/'))return sessionBuilder(h.split('/')[1]||undefined);if(h==='join')return join();if(h==='play')return play();if(h==='about')return about();if(h.startsWith('scenario/'))return detail(h.split('/')[1]);if(h.startsWith('session/'))return sessionView(h.split('/')[1]);if(h.startsWith('terminal/'))return terminal(h.split('/')[1]);if(h.startsWith('tv/'))return tv(h.split('/')[1]);if(h.startsWith('kit/'))return printKit(h.split('/')[1]);if(h.startsWith('test/'))return testScenario(h.split('/')[1]);return home()}
subscribe(m=>{const h=location.hash;if(m.type==='session:update'&&state.session?.id===m.payload?.sessionId)state.session=getSession(state.session.id)||state.session;if(m.type==='progress'&&state.session?.id===m.payload?.sessionId&&state.team?.id===m.payload?.teamId)state.progress=loadProgress(state.session.id,state.team.id)||state.progress;if((h.startsWith('#session/')||h.startsWith('#tv/')||h.startsWith('#terminal/')||h==='#play')&&['progress','session:update'].includes(m.type))render()});addEventListener('hashchange',render);initAccessibility();registerSW();
const q=new URLSearchParams(location.search);if(q.get('team')){const payload=parseTeamPayload(q.get('team'));if(payload&&byId(payload.scenarioId)){const {session,team}=createImportedSession(payload);history.replaceState({},'',location.pathname+location.hash);state.session=session;state.team=team;state.scenario=byId(session.scenarioId);state.progress=ensureProgress(session,team,state.scenario);location.hash='#play'}else render()}else render();
